import { ColumnDef, Row } from '@tanstack/react-table';
import EditIcon from '@/components/icons/EditIcon';
import TrashIcon from '@/components/icons/TrashIcon';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import DeletePopup from '@/components/Popups/DeletePopup';
import { toast } from 'sonner';
import { RoleRow } from '../../types/roles.types';
import { useHasPermission } from '../../hooks/usePermission';

const ActionsCell = ({ row }: { row: Row<RoleRow> }) => {
    const navigate = useNavigate();
    const [showDeletePopup, setShowDeletePopup] = useState(false);
    const canEdit = useHasPermission('edit_role');
    const canDelete = useHasPermission('delete_role');
    const isSuper = row.original.slug === 'super_admin';

    return (
        <>
            <div className="flex items-center gap-7">
                {canEdit && (
                    <button
                        type="button"
                        onClick={() => navigate(`/access-control/roles/${row.original.id}/edit`)}
                        className="text-primary hover:text-primary/80"
                    >
                        <EditIcon className="text-primery-blue-400" />
                    </button>
                )}
                {canDelete && !isSuper && (
                    <button type="button" onClick={() => setShowDeletePopup(true)}>
                        <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                    </button>
                )}
            </div>
            {showDeletePopup && (
                <DeletePopup
                    open={showDeletePopup}
                    text="هل أنت متأكد أنك تريد حذف هذا الدور؟"
                    endpoint={endpoints.accessControl.roleDelete + row.original.id}
                    handleCancel={() => setShowDeletePopup(false)}
                    handleSuccess={() => {
                        toast.success('تم حذف الدور');
                        setShowDeletePopup(false);
                        row.original.refreshTable?.();
                    }}
                />
            )}
        </>
    );
};

export const columns: ColumnDef<RoleRow>[] = [
    {
        accessorKey: 'name',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                اسم الدور
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.name}
            </div>
        ),
    },
    {
        accessorKey: 'is_active',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">الحالة</div>
        ),
        cell: ({ row }) => {
            const active = row.original.is_active === 1 || row.original.is_active === true;
            return (
                <div className="text-sm px-4 py-3 text-white-blue-800">{active ? 'مفعّل' : 'غير مفعّل'}</div>
            );
        },
    },
    {
        id: 'actions',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">إجراءات</div>
        ),
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
